  "johto:imp:003:00": ["ac65b647e723", "Da unos pasos hacia el oeste para recibir las Deportivas.", "向西走几步，领取跑步鞋。"],
  "johto:imp:003:01": ["3b10cdc06596", "Ve al noroeste de la Tienda Pokémon para recibir la Tarjeta Mapa.", "前往宝可梦商店的西北方，领取地图卡。"],
